import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Il paradosso del mentitore","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/b_aritmetica-e-numeri/bf/bfca.md","filePath":"lezioni/b_aritmetica-e-numeri/bf/bfca.md"}`),a={name:`lezioni/b_aritmetica-e-numeri/bf/bfca.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="il-paradosso-del-mentitore" tabindex="-1">Il paradosso del mentitore <a class="header-anchor" href="#il-paradosso-del-mentitore" aria-label="Permalink to “Il paradosso del mentitore”">​</a></h1><p>Se faccio l&#39;affermazione:</p><p><strong>[Io sto mentendo]{.text-blue}</strong></p><p>Questa affermazione è vera oppure è falsa?</p><ul><li>Se l&#39;affermazione fosse vera direi la verità e quindi l&#39;affermazione è falsa</li><li>Se l&#39;affermazione fosse falsa direi una bugia e quindi l&#39;affermazione è vera</li></ul><p>Comunque io la giri questa frase non ha senso perché non puoi affermare se è vera oppure falsa. Questo è un paradosso che si rifà al paradosso del mentitore (VI secolo A.C.):</p><p><strong>[Tutti gli atenesi sono bugiardi; se io vi dico che sto mentendo, sapendo che sono ateniese, vi dico la verità?]{.text-blue}</strong></p><ul><li>Se vi dico la verità vuol dire che sto mentendo quindi non vi dico la verità</li><li>Se non vi dico la verità vuol dire che non sto mentendo quindi è vero che sto mentendo e vi dico la verità</li></ul><p>In pratica abbiamo un sistema autoreferente, cioè un qualcosa che si rifà a sé stesso, e quindi abbiamo un risultato che non possiamo dire se sia vero o falso; diremo quindi che abbiamo un&#39;antinomia, od anche un paradosso.</p><hr>`,10)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};